import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-05-11","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-05-11","date":"2021-05-11T00:00:00.000Z","updated":"2021-05-12T00:00:00.000Z","tags":["Ceph","OpenStack集成","NFS模块","存储解决方案","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-11.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-11.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-05-11.md"};function p(o,e,i,l,_,c){return a(),r("div",null,[...e[0]||(e[0]=[s("<p>本次会议主要讨论了OpenStack与Ceph集成中的NFS模块问题，与会人员包括OpenStack与Ceph开发团队成员。会议主要议题包括：</p><ol><li><p><strong>NFS模块现状与挑战</strong>：目前NFS模块存在多个模块和限制，需要找到解决方案以推动OpenStack的发展。仪表盘模块功能良好，但需要与新的NFS模块集成，该模块目前尚未完全功能完善。</p></li><li><p><strong>OpenStack与Ceph集成中的NFS模块问题</strong>：需要部署Ganesha和Pacemaker，但存在配置和部署的复杂性。现有的NFS模块不支持NFSv3，仅支持NFSv4.1及以上版本。</p></li><li><p><strong>短期与长期解决方案讨论</strong>：</p><ul><li><strong>短期解决方案</strong>：使用TripleO Ansible部署Ganesha和Pacemaker，类似于Stephansible的方式；确保部署的Ganesha能够与Ceph集群通信，并正确配置。</li><li><strong>长期解决方案</strong>：使用Cephadm管理NFS守护进程和入口服务；Manila直接与Cephadm交互，动态部署和管理Ganesha集群。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li><strong>短期行动</strong>：完成TripleO Ansible部署Ganesha和Pacemaker的脚本；确保迁移过程中现有客户的平稳过渡。</li><li><strong>长期行动</strong>：完善Cephadm的NFS模块，确保其支持所有必要的功能；简化Manila代码，使其能够利用新的NFS模块接口；开发迁移工具，帮助客户从旧系统迁移到新系统。</li></ul></li></ol><p>会议明确了OpenStack与Ceph集成中NFS模块的问题，并制定了短期和长期的解决方案。开发团队将按照会议确定的行动计划，逐步推进项目的进展。</p>",3)])])}const S=t(n,[["render",p]]);export{g as __pageData,S as default};
